import {Chess} from './vendor/chess.js';
import {SKILLS,LESSONS,clamp,startingTarget,newCoach,adapt,recommendSkill,pickPuzzle,positionKey,lessonFor,weekKey,localDate,normalize,validBackup} from './core.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('en-US'), duration=n=>Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');
const names={p:'pawn',n:'knight',b:'bishop',r:'rook',q:'queen',k:'king'},glyph={p:'♟',n:'♞',b:'♝',r:'♜',q:'♛',k:'♚'};
const tasks=[['puzzles','Solve three puzzles','10 min'],['rapid','Play a rapid game','15 + 10'],['review','Review one game','10 min'],['lesson','Learn one skill','10 min'],['endgame','Practice an endgame','10 min']];
let state,bank=[],legacy=[],puzzleMap=new Map(),view='dashboard',selectedSkill=null,selectedSquare=null,flipped=false,paused=false,feedback=null,replayStep=null,review=null,journalFilter='all',pendingPromotion=null,lastTick=Date.now(),toastTimeout;
try{state=normalize(JSON.parse(localStorage.getItem('chess-daily')))}catch{state=normalize(null)}
function save(){try{localStorage.setItem('chess-daily',JSON.stringify(state));return true}catch{toast('Your browser could not save. Please export a backup before leaving.',true);return false}}
function toast(message,persistent=false){clearTimeout(toastTimeout);$('#toast').textContent=message;$('#toast').style.display='block';if(!persistent)toastTimeout=setTimeout(()=>$('#toast').style.display='none',4500)}
function currentRating(){return state.ratings.at(-1)?.value??state.profile?.currentRating??null}
function skillCoach(skill){state.coach||=newCoach(currentRating());return state.coach[skill]}
function progressPercent(){let r=currentRating(),start=state.profile?.startRating,goal=state.profile?.goal||1500;return r==null||start==null||goal<=start?0:clamp((r-start)/(goal-start)*100,0,100)}
function relativeTime(seconds){return seconds<60?Math.round(seconds)+' sec':(seconds/60).toFixed(1)+' min'}
function navigation(){const labels={dashboard:'YOUR WEEKLY WORKSPACE',training:'TEN MINUTES, ONE SKILL',journal:'YOUR LEARNING JOURNAL',progress:'THE LONG GAME',settings:'A PLAN THAT FITS YOU',review:'LOOK BACK. LEARN SOMETHING.'};$('#page-label').textContent=labels[view];$('#today').textContent=new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view||view==='review'&&b.dataset.view==='journal'));const goal=state.profile?.goal||1500;$('#side-goal').innerHTML=`<div class="eyebrow">YOUR LONG-TERM GOAL</div><strong>${fmt(goal)} <small>rating</small></strong><div class="progress-track"><span style="width:${progressPercent()}%"></span></div><small>${currentRating()==null?'Let’s find your starting point.':fmt(currentRating())+' now · one move at a time'}</small>`}
function go(v){flushTime();view=v;selectedSquare=null;feedback=null;if(v==='training')paused=false;lastTick=Date.now();render();window.scrollTo({top:0,behavior:'instant'})}
function render(){navigation();let html;if(!state.profile&&(view==='dashboard'||view==='training'||view==='settings'))html=setupPage(true);else if(view==='dashboard')html=dashboardPage();else if(view==='training')html=trainingPage();else if(view==='journal')html=journalPage();else if(view==='progress')html=progressPage();else if(view==='settings')html=setupPage(false);else if(view==='review')html=reviewPage();$('#content').innerHTML=html;bind();}
function setupPage(first){const p=state.profile||{},known=p.currentRating!=null||currentRating()!=null;return `<div class="setup"><div class="intro"><div class="eyebrow">${first?'A BETTER WAY TO PRACTICE':'YOUR TRAINING PLAN'}</div><h1 style="margin-top:13px">${first?'Start where you are.':'Make this your training room.'}</h1><p>${first?'Tell us a little about your chess. We’ll find the right challenge together.':'Your game rating and puzzle difficulty are separate. Your solves guide the training.'}</p></div><form id="profile-form" class="panel"><h2>${first?'First, your starting point':'Your rating & goal'}</h2><p class="fine">An Elo is a chess rating. It’s completely fine if you don’t have one yet.</p><div class="setup-choices"><label class="choice"><input type="radio" name="known" value="yes" ${known?'checked':''}>I know my rating</label><label class="choice"><input type="radio" name="known" value="no" ${known?'':'checked'}>I don’t know my rating</label></div><div class="form-grid"><label class="form-field">Current game rating<input id="current-rating" name="current" type="number" min="100" max="3500" step="1" value="${known?currentRating():''}" placeholder="For example, 950" ${known?'required':'disabled'}><small>Use a rapid rating from the platform you play on.</small></label><label class="form-field">The rating I’m working toward<input name="goal" type="number" min="100" max="3500" step="1" value="${p.goal||1500}" required><small>A direction to work toward, without a deadline.</small></label><label class="form-field full">Chess platform / time control<input name="platform" value="${esc(p.platform||'')}" placeholder="For example, Chess.com rapid"><small>Optional. Keep rating updates comparable.</small></label></div>${!first?'<label class="inline-check section-space"><input type="checkbox" name="recalibrate">Start a fresh difficulty calibration from this rating</label><p class="fine muted">Your journal and used positions will be kept.</p>':''}<button class="button primary">${first?'Create my training plan':'Save training plan'}</button><p class="fine muted" style="margin:14px 0 0;text-align:center">${known?'We’ll start near your level and adjust with each puzzle.':'No rating? We start easy. Fast, accurate solves bring harder puzzles.'}</p></form>${first?'<div class="setup-benefits"><div><b>Real positions</b>Rated puzzles from real games.</div><div><b>Your pace</b>Difficulty follows your answers.</div><div><b>Fresh practice</b>No automatic position repeats.</div></div>':`<div class="panel section-space"><h2>How your coach adjusts</h2><p class="fine">A clean solve means no incorrect moves, hints, or solution reveals. Two or more quick, clean solves raise difficulty more quickly. A thoughtful solve keeps the challenge manageable. Mistakes hold the level steady; repeated struggles bring a small step down.</p><p class="fine">Time is measured while the training room is visible and unpaused. Longer lines get more thinking time. Puzzle ratings are training difficulty, not an estimate of your game rating.</p><p class="fine">There are ${fmt(bank.length)} real positions. New sessions avoid both used IDs and used board positions. If a skill runs out, the app asks you to choose another skill.</p><div class="row wrap"><button class="button secondary" type="button" data-export>Export my backup</button><label class="button secondary" style="cursor:pointer">Restore a backup<input type="file" class="restore-file" accept="application/json" hidden></label></div><p class="fine muted" style="margin:15px 0 0">Your records live in this browser. Export a backup to move them to another device.</p></div>`}</div>`}
function chart(){let start=state.profile?.startRating,rows=[...(start!=null&&state.ratings[0]?.value!==start?[{value:start,date:'Starting point'}]:[]),...state.ratings];if(!rows.length)return '<div class="empty" style="padding:25px 10px"><p>No game rating yet. Your first update will start this chart.</p><button class="button secondary small" data-goto="progress">Record a rating</button></div>';let goal=state.profile?.goal||1500,low=Math.min(...rows.map(r=>r.value),goal)-100,high=Math.max(...rows.map(r=>r.value),goal)+100;let y=v=>165-(v-low)/(high-low)*140,xy=rows.map((r,i)=>[24+i*640/Math.max(1,rows.length-1),y(r.value)]);return `<svg class="chart" viewBox="0 0 750 195" role="img" aria-label="Game rating history: ${rows.map(r=>r.value).join(', ')}. Goal ${goal}."><line x1="24" x2="690" y1="${y(goal)}" y2="${y(goal)}" stroke="#ccd9bf" stroke-dasharray="5 6"/><text x="700" y="${y(goal)+4}" fill="#8b9b7d" font-size="11">${goal}</text><polyline points="${xy.map(x=>x.join(',')).join(' ')}" fill="none" stroke="#74945b" stroke-width="3"/>${xy.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#2c5c43"><title>${esc(rows[i].date)}: ${rows[i].value}</title></circle>`).join('')}</svg><div class="chart-labels"><span>${fmt(rows[0].value)} · ${rows[0].date==='Starting point'?'starting point':esc(rows[0].date)}</span><span>${fmt(rows.at(-1).value)} · latest</span></div>`}
function dashboardPage(){const w=weekKey(),today=localDate(),sessions=state.sessions.filter(s=>s.date>=w&&s.date<=today),checks=state.checks[w]||{},count=tasks.filter(t=>checks[t[0]]).length,minutes=sessions.reduce((n,s)=>n+(s.version===2?s.seconds/60:Number(s.minutes)),0),all=state.sessions.filter(s=>s.version===2).flatMap(s=>s.results),clean=all.filter(x=>x.clean).length,skill=state.active?.skill||recommendSkill(state),c=skillCoach(skill),available=bank.filter(p=>!state.seen.includes(p.id)).length;
return `<div class="intro row"><div><div class="eyebrow">SMALL MOVES. REAL PROGRESS.</div><h1 style="margin-top:10px">A little practice. A better player.</h1><p>Your weekly rhythm, with the right amount of challenge.</p></div><button class="button primary" data-goto="training">${state.active?'Continue training':'Start 10-minute session'}</button></div><div class="metrics"><div class="metric"><div class="eyebrow">CURRENT GAME RATING</div><div class="metric-number">${currentRating()==null?'Unrated':fmt(currentRating())}<small> / ${fmt(state.profile.goal)}</small></div><div class="metric-sub">${currentRating()==null?'Your training still starts right here.':Math.max(0,state.profile.goal-currentRating())===0?'Goal reached. Keep building good habits.':fmt(state.profile.goal-currentRating())+' points to your goal'}</div></div><div class="metric"><div class="eyebrow">PRACTICE THIS WEEK</div><div class="metric-number">${minutes?minutes.toFixed(1):'0'} <small>minutes</small></div><div class="metric-sub">${sessions.length} session${sessions.length===1?'':'s'} logged</div></div><div class="metric"><div class="eyebrow">PUZZLE ACCURACY</div><div class="metric-number">${all.length?Math.round(clean/all.length*100)+'%':'—'} <small>${all.length?'first try':'just getting started'}</small></div><div class="metric-sub">${all.length?clean+' clean solve'+(clean===1?'':'s')+' from '+all.length+' puzzles':'Accuracy matters more than speed.'}</div></div></div><div class="dashboard-grid"><div class="hero-card"><div class="eyebrow">${state.active?'YOUR SESSION IS WAITING':'RECOMMENDED FOR YOU'}</div><h2>${SKILLS[skill].short}.</h2><p>${SKILLS[skill].description} Three fresh puzzles, adjusted one at a time to your performance.</p><div class="hero-meta"><span>${SKILLS[skill].name}</span><span>Target ${fmt(c.target)}</span><span>10 minutes</span></div><button class="button light" data-goto="training">${state.active?'Continue session':'Open training room'}</button><div class="hero-piece" aria-hidden="true">${SKILLS[skill].icon}</div></div><div class="panel"><div class="row"><h2 style="margin:0">This week’s plan</h2><span class="badge">${count} of 5</span></div><div class="progress-track"><span style="width:${count*20}%"></span></div>${tasks.map(t=>`<label class="check-item"><input type="checkbox" data-task="${t[0]}" ${checks[t[0]]?'checked':''}><span>${t[1]}</span><small>${t[2]}</small></label>`).join('')}</div></div><div class="dashboard-grid section-space"><div class="panel"><div class="row"><h2 style="margin:0">The road to ${fmt(state.profile.goal)}</h2><button class="button secondary small" data-goto="progress">Update rating</button></div>${chart()}</div><div class="coach-note"><div class="eyebrow">A COACH THAT FOLLOWS YOUR PACE</div><h2>${all.length?'Here’s your next step.':'Let’s find your sweet spot.'}</h2><p>${esc(c.reason)}</p><p style="margin-top:12px">${fmt(available)} fresh positions remain. Your game rating stays separate from puzzle difficulty.</p></div></div><div class="section-space"><div class="row"><h2 style="margin:0">Your four building blocks</h2><span class="fine muted">One skill per session</span></div><div class="skill-cards">${Object.entries(SKILLS).map(([k,s])=>`<div class="skill-card"><div class="symbol">${s.icon}</div><b>${s.name}</b><small>${skillCoach(k).total?skillCoach(k).solved+' clean / '+skillCoach(k).total+' attempted':'Ready when you are'} · target ${fmt(skillCoach(k).target)}</small></div>`).join('')}</div></div>`}
function trainingPage(){if(state.active)return activePage();let skill=selectedSkill||recommendSkill(state),c=skillCoach(skill),p=pickPuzzle(bank,skill,c.target,state.seen,state.seenPositions),lesson=p?lessonFor(state,skill,p):null;return `<div class="training-start"><div class="intro"><div class="eyebrow">YOUR NEXT TEN MINUTES</div><h1 style="margin-top:10px">Train at your edge.</h1><p>Pick one skill. Solve three real positions. Leave with one useful idea.</p></div><div class="skill-picker">${Object.entries(SKILLS).map(([k,s])=>`<button class="skill-choice ${skill===k?'active':''}" data-skill="${k}" aria-pressed="${skill===k}"><span>${s.icon}</span><b>${s.name}</b><small>${s.description}</small>${k===recommendSkill(state)?'<div class="badge" style="margin-top:10px">Recommended</div>':''}</button>`).join('')}</div><div class="panel"><div class="row wrap"><div><div class="eyebrow">TODAY’S FOCUS · ${SKILLS[skill].name.toUpperCase()}</div><h2 style="margin-top:12px">${lesson?esc(lesson.title):'You’ve used every position in this skill.'}</h2></div><span class="badge">Difficulty target ${fmt(c.target)}</span></div><p>${lesson?esc(lesson.body):'Choose another skill for fresh positions. We won’t automatically repeat a board you’ve seen.'}</p><div class="instruction"><b>Your pace sets the challenge.</b> ${esc(c.reason)} ${p&&Math.abs(p.rating-c.target)>175?'The closest fresh puzzle in this skill is rated '+p.rating+'.':''}</div><button id="begin-session" class="button primary" ${p?'':'disabled'}>Start my session</button><p class="fine muted" style="margin:15px 0 0">2 minutes: learn the idea · 6 minutes: puzzles · 2 minutes: reflect<br>Click a piece, then its destination. Your opponent’s replies play automatically.</p></div></div>`}
function beginSession(){let skill=selectedSkill||recommendSkill(state),p=pickPuzzle(bank,skill,skillCoach(skill).target,state.seen,state.seenPositions);if(!p)return toast('No fresh puzzles remain in this skill. Choose another.');let lesson=lessonFor(state,skill,p);state.active={id:Date.now(),version:2,date:localDate(),skill,lessonId:lesson.id,lessonTitle:lesson.title,lessonBody:lesson.body,seconds:0,results:[],puzzle:null,mistakes:'',tip:SKILLS[skill].tip,targetStart:skillCoach(skill).target,stage:'puzzles'};newPuzzle(p);paused=false;lastTick=Date.now();save();render()}
function newPuzzle(preselected){const d=state.active,p=preselected||pickPuzzle(bank,d.skill,skillCoach(d.skill).target,state.seen,state.seenPositions);if(!p){d.stage='notes';save();toast('No fresh positions remain for this skill. Save your session, then choose another.');return}state.seen.push(p.id);state.seenPositions.push(positionKey(p.fen));d.puzzle={id:p.id,cursor:0,seconds:0,mistakes:[],hints:0,done:false,revealed:false,moves:[],targetBefore:skillCoach(d.skill).target};selectedSquare=null;replayStep=null;feedback=null;save()}
function activeGame(){const p=state.active?.puzzle;if(!p)return null;const data=puzzleMap.get(p.id),game=new Chess(data.fen);const limit=p.done?(replayStep??data.moves.length):p.cursor;for(const m of (p.alternative?[p.alternative]:data.moves).slice(0,limit))game.move(uci(m));return game}
const uci=m=>({from:m.slice(0,2),to:m.slice(2,4),...(m[4]?{promotion:m[4]}:{})});
function boardHTML(game,{interactive=false,black=false,last=null,hint=null,staticBoard=false}={}){let files=black?'hgfedcba':'abcdefgh',ranks=black?'12345678':'87654321',legals=interactive&&selectedSquare?game.moves({square:selectedSquare,verbose:true}).map(m=>m.to):[];return `<div class="board" role="group" aria-label="Chessboard. ${game.turn()==='w'?'White':'Black'} to move.">${[...ranks].flatMap((r,ri)=>[...files].map((f,fi)=>{let sq=f+r,p=game.get(sq),dark=('abcdefgh'.indexOf(f)+Number(r))%2===0,isLast=last&&(sq===last.from||sq===last.to),label=`${sq}${p?', '+(p.color==='w'?'White':'Black')+' '+names[p.type]:', empty'}${selectedSquare===sq?', selected':''}`;return `<button class="square ${dark?'dark':''} ${isLast?'last':''} ${selectedSquare===sq&&interactive?'selected':''} ${hint===sq?'hint':''}" ${interactive?`data-square="${sq}"`:''} aria-label="${label}" ${staticBoard?'tabindex="-1"':''}>${p?`<span class="piece ${p.color==='w'?'white':'black'}" aria-hidden="true">${glyph[p.type]}</span>`:''}${legals.includes(sq)?'<span class="legal-dot" aria-hidden="true"></span>':''}${fi===0||ri===7?`<span class="coord" aria-hidden="true">${fi===0?r:''}${ri===7?f:''}</span>`:''}</button>`})).join('')}</div>`}
function sessionHeader(d){return `<div class="row session-top"><div><div class="eyebrow">${SKILLS[d.skill].name.toUpperCase()} · FOCUSED PRACTICE</div><h1>${d.stage==='notes'?'Keep the useful part.':esc(d.lessonTitle)}</h1><div class="session-steps" aria-label="${d.results.length} of 3 puzzles complete">${[0,1,2].map(i=>`<span class="step ${i<d.results.length?'done':i===d.results.length?'current':''}"></span>`).join('')}</div></div><div class="session-clock"><div class="clock"><small>SESSION TIME</small><span id="session-time">${duration(d.seconds)}</span></div>${d.stage==='puzzles'?`<button class="button secondary small" id="pause">${paused?'Resume':'Pause'}</button>`:'<span class="badge">Ready to log</span>'}</div></div>`}
function activePage(){const d=state.active;if(d.stage==='notes')return notesPage(d);const a=d.puzzle,p=puzzleMap.get(a.id),game=activeGame(),orientation=(new Chess(p.fen).turn()==='b')!==flipped,turn=(new Chess(p.fen)).turn()==='w'?'White':'Black',last=game.history({verbose:true}).at(-1),done=a.done,result=d.results.find(r=>r.id===a.id),completedInfo=done?`<div class="feedback"><b>${a.revealed?'Solution reviewed.':a.mistakes.length||a.hints?'You worked through it.':'Puzzle solved.'}</b>${esc(result.reason)}<div class="fine" style="margin-top:6px">${result.clean?'Clean solve':'Learning solve'} · ${relativeTime(result.seconds)} · next target ${fmt(result.targetAfter)}</div></div>`:'';
return `${sessionHeader(d)}<div class="training-layout"><div class="board-panel"><div class="row board-top"><span class="turn-label"><span class="color-dot ${turn==='Black'?'black':''}"></span>${done?'Solution review':turn+' to move'}</span><span class="badge">Puzzle ${d.results.length+(done?0:1)} of 3 · rated ${p.rating}</span></div><div class="board-wrap">${boardHTML(game,{interactive:!done&&!paused,black:orientation,last,hint:a.hints>=2&&!done?p.moves[a.cursor]?.slice(0,2):null})}${paused?'<div class="paused-overlay"><h2>Take your time.</h2><p>Your timer is paused.</p><button class="button primary" id="resume-board">Resume puzzle</button></div>':''}</div><div class="board-caption"><span>${done?'Use the review controls to follow the line.':'Select a piece, then select its destination.'}</span><button id="flip-board">Flip board</button></div>${done?`<div class="replay-controls"><button class="button secondary" id="replay-back" ${(replayStep??p.moves.length)===0?'disabled':''}>Previous move</button><button class="button secondary" id="replay-next" ${(replayStep??p.moves.length)>=p.moves.length?'disabled':''}>Next move</button></div>`:`<div class="move-line">${a.moves.map((m,i)=>`<span class="move-chip ${i%2?'opponent':''}">${i%2?'Reply: ':''}${esc(m.san)}</span>`).join('')}</div>`}</div><div class="training-info"><div class="panel"><div class="row"><div class="eyebrow">${done?'WHAT TO TAKE AWAY':'YOUR CHALLENGE'}</div><span class="fine muted" id="puzzle-time">${relativeTime(a.seconds)}</span></div><h2>${SKILLS[d.skill].short}.</h2>${completedInfo}${feedback&&!done?`<div class="feedback ${feedback.error?'error':''}" role="status"><b>${esc(feedback.title)}</b>${esc(feedback.text)}</div>`:''}${!done?`<p>${a.cursor?'Keep going. Find your next move in the winning line.':SKILLS[d.skill].description} ${p.themes.includes('mateIn1')?'Find checkmate in one move.':p.themes.includes('mateIn2')?'Look for a forced checkmate in two moves.':p.themes.includes('mateIn3')?'Look for a forced checkmate in three moves.':'Find the best continuation.'}</p>${a.hints?`<div class="instruction">${a.hints>=2?'The piece to move is highlighted. Select it and look at its legal destinations.':hintText(d.skill,game,p)}</div>`:''}<div class="hint-actions"><button class="button secondary" id="hint" ${paused||a.hints>=2?'disabled':''}>${a.hints>=2?'Piece highlighted':a.hints?'Show piece to move':'Get a hint'}</button><button class="button quiet" id="reveal" ${paused?'disabled':''}>Show solution</button></div><p class="fine muted" style="margin:13px 0 0">Hints are here to help. Assisted solves won’t raise the difficulty.</p>`:`<p>${esc(SKILLS[d.skill].tip)}</p><button class="button primary" id="next-puzzle" style="width:100%">${d.results.length>=3?'Finish & write my takeaway':'Next puzzle'}</button><details class="section-space"><summary class="fine" style="cursor:pointer;font-weight:650">Full solution, step by step</summary><div class="solution-line">${solutionHTML(a.alternative?{...p,moves:[a.alternative]}:p)}</div></details>`}</div><div class="coach-note"><div class="eyebrow">ONE IDEA FOR THIS SESSION</div><h3 style="margin-top:12px">${esc(d.lessonTitle)}</h3><p>${esc(d.lessonBody)}</p></div><div class="fine muted" style="margin-top:12px">Your target: ${fmt(skillCoach(d.skill).target)} · ${a.mistakes.length} incorrect move${a.mistakes.length===1?'':'s'} · ${a.hints} hint${a.hints===1?'':'s'}<br><a href="${p.url}" target="_blank" rel="noreferrer">View original Lichess puzzle</a></div></div></div>`}
function hintText(skill,game,p){if(game.inCheck())return 'Your king is in check. First look for a legal way to escape, block, or capture the checking piece.';return {forks:'Look for a move that attacks two targets. A check can make the first threat forcing.',pins:'Trace the lines of bishops, rooks, and queens. Which defender has a valuable piece behind it?',checkmates:'Start with checks. For each one, count the king’s safe squares, captures, and possible blocks.',calculation:'Compare checks and captures. Picture the opponent’s strongest reply, then your next move.'}[skill]}
function flushTime(){const now=Date.now(),delta=Math.min(3,Math.floor((now-lastTick)/1000));if(delta>0){lastTick+=delta*1000;const d=state.active;if(d&&d.stage==='puzzles'&&view==='training'&&!paused&&!document.hidden){let before=d.seconds;d.seconds+=delta;if(d.puzzle&&!d.puzzle.done)d.puzzle.seconds+=delta;if(before<600&&d.seconds>=600)toast('Ten minutes reached. Finish your current puzzles, then save your takeaway.');save()}}}
function trySquare(sq){const a=state.active?.puzzle;if(!a||a.done||paused)return;const game=activeGame(),piece=game.get(sq),solver=new Chess(puzzleMap.get(a.id).fen).turn();if(piece?.color===solver){selectedSquare=selectedSquare===sq?null:sq;render();return}if(!selectedSquare)return toast('Select one of your pieces first.');let from=selectedSquare;let candidates=game.moves({square:from,verbose:true}).filter(m=>m.to===sq);if(!candidates.length){feedback={error:true,title:'That move isn’t legal.',text:game.inCheck()?'Your king is in check. Choose a move that makes it safe.':'Choose a highlighted destination. Remember that your king must stay safe.'};selectedSquare=null;render();return}if(candidates.some(m=>m.promotion)){pendingPromotion={from,to:sq};$('#promotion .promotion-options').innerHTML=['q','r','b','n'].filter(t=>candidates.some(m=>m.promotion===t)).map(t=>`<button data-promote="${t}" aria-label="Promote to ${names[t]}">${glyph[t]}<small>${names[t]}</small></button>`).join('');$$('[data-promote]').forEach(b=>b.onclick=()=>{const move={...pendingPromotion,promotion:b.dataset.promote};pendingPromotion=null;$('#promotion').close();submitMove(move)});$('#promotion').showModal();return}submitMove({from,to:sq})}
function submitMove(move){flushTime();const d=state.active,a=d.puzzle,p=puzzleMap.get(a.id),game=activeGame(),chosen=game.move(move),code=chosen.from+chosen.to+(chosen.promotion||''),expected=p.moves[a.cursor],alternativeMate=p.themes.includes('mateIn1')&&game.isCheckmate();selectedSquare=null;if(code!==expected&&!alternativeMate){a.mistakes.push({move:chosen.san,ply:a.cursor,seconds:a.seconds});feedback={error:true,title:'A legal move, but there’s a stronger one.',text:'The board is unchanged. '+SKILLS[d.skill].tip+' Try again, or use a hint.'};save();render();return}a.moves.push({san:chosen.san,uci:code});a.cursor++;if(alternativeMate){a.alternative=code;a.cursor=p.moves.length;finishPuzzle(false);return}if(a.cursor>=p.moves.length){finishPuzzle(false);return}const reply=game.move(uci(p.moves[a.cursor]));a.moves.push({san:reply.san,uci:p.moves[a.cursor]});a.cursor++;feedback={title:'Correct. Now think one move further.',text:'Your opponent played '+describeMove(reply)+'. Find your next move.'};save();render()}
function finishPuzzle(revealed){const d=state.active,a=d.puzzle;if(a.done)return;a.done=true;a.revealed=revealed;const p=puzzleMap.get(a.id),result={id:p.id,seconds:Math.max(1,a.seconds),clean:!revealed&&!a.mistakes.length&&!a.hints,mistakes:[...a.mistakes],hints:a.hints,revealed,playerMoves:Math.ceil(p.moves.length/2),rating:p.rating,targetBefore:a.targetBefore,moves:[...a.moves],alternative:a.alternative||null};let c=adapt(skillCoach(d.skill),result);state.coach[d.skill]=c;result.targetAfter=c.target;result.reason=c.reason;d.results.push(result);replayStep=p.moves.length;feedback=null;save();render()}
function describeMove(m){return `${names[m.piece]} ${m.from} to ${m.to}${m.captured?', capturing a '+names[m.captured]:''}${m.promotion?', promoting to a '+names[m.promotion]:''}${m.san.endsWith('#')?', checkmate':m.san.endsWith('+')?', giving check':''}`}
function annotations(p){let game=new Chess(p.fen),rows=[];const solver=game.turn();for(let i=0;i<p.moves.length;i++){const m=game.move(uci(p.moves[i]));let text=describeMove(m)+'.';if(i%2===0){if(game.isCheckmate())text+=' The king cannot escape, capture the attacker, or block the check.';else if(m.san.endsWith('+'))text+=' The opponent must answer the check before carrying out another threat.';if(p.skill==='forks'){let targets=[];for(const row of game.board())for(const pc of row)if(pc&&pc.color!==solver&&pc.type!=='p'&&game.attackers(pc.square,solver).includes(m.to))targets.push(names[pc.type]+' on '+pc.square);if(targets.length>=2)text+=' This piece attacks the '+targets.join(' and the ')+': a double attack.';}if(i===p.moves.length-1&&p.skill==='pins')text+=' The pinned defender is the key idea in this line. Check the piece behind it before judging a recapture.';if(i===p.moves.length-1&&p.skill==='calculation')text+=' Notice how the forcing moves lead to this position; calculate the reply before starting the sequence.';}
rows.push({move:m.san,text,opponent:i%2===1,fen:game.fen(),from:m.from,to:m.to});}return rows}
function solutionHTML(p){return annotations(p).map((r,i)=>`<div class="solution-step ${r.opponent?'opponent':''}"><b>${r.opponent?'Opponent’s reply':'Your move'} · ${esc(r.move)}</b>${esc(r.text)}</div>`).join('')}
function notesPage(d){const clean=d.results.filter(r=>r.clean).length;return `${sessionHeader(d)}<div class="summary-grid"><div class="panel"><div class="eyebrow">A SESSION WORTH KEEPING</div><h2 style="margin-top:12px">${d.results.length} puzzles. One useful idea.</h2><p>${clean} solved without help · ${relativeTime(d.seconds)} practiced · ${SKILLS[d.skill].name}</p><div class="result-list">${d.results.map((r,i)=>`<div class="result-row"><span class="result-icon">${r.clean?'✓':'◇'}</span><div><b>Puzzle ${i+1} · rated ${r.rating}</b><small>${r.clean?'Solved first try':r.revealed?'Solution reviewed':'Solved with help'} · ${relativeTime(r.seconds)}</small></div><span>${r.mistakes.length} mistake${r.mistakes.length===1?'':'s'}</span></div>`).join('')}</div><div class="instruction">${esc(skillCoach(d.skill).reason)}<br><b>Next ${SKILLS[d.skill].name.toLowerCase()} target: ${fmt(skillCoach(d.skill).target)}</b></div></div><form class="panel" id="save-session"><h2>What will you remember?</h2><div class="form-grid"><label class="form-field full">Session date<input data-note="date" type="date" max="${localDate()}" value="${esc(d.date)}" required></label><label class="form-field full">Mistakes I noticed<textarea data-note="mistakes" placeholder="For example: I stopped calculating before their best reply.">${esc(d.mistakes)}</textarea></label><label class="form-field full">My practical tip<textarea data-note="tip" required>${esc(d.tip)}</textarea><small>Make it something you can use in your next game.</small></label></div><button class="button primary section-space" style="width:100%">Save session to journal</button><p class="fine muted" style="margin-top:12px">Your reflection saves as you type.</p></form></div>`}
function saveSession(){const d=state.active;state.sessions.push({...d,puzzle:undefined,targetEnd:skillCoach(d.skill).target});state.sessions.sort((a,b)=>a.date.localeCompare(b.date));if(d.results.length>=3){state.checks[weekKey(new Date(d.date+'T12:00:00'))]||={};state.checks[weekKey(new Date(d.date+'T12:00:00'))].puzzles=true;state.checks[weekKey(new Date(d.date+'T12:00:00'))].lesson=true;}state.active=null;selectedSkill=null;save();go('journal');toast('Session saved. Your next session will use fresh positions.')}
function journalPage(){const sessions=state.sessions.filter(s=>journalFilter==='all'||s.skill===journalFilter||s.version!==2&&legacy.find(l=>l.id===s.lesson)?.skill.toLowerCase()===journalFilter);return `<div class="intro"><div class="eyebrow">PROGRESS YOU CAN LOOK BACK ON</div><h1 style="margin-top:10px">Your session journal</h1><p>${state.sessions.length} session${state.sessions.length===1?'':'s'} recorded. Keep the patterns, the mistakes, and the small wins.</p></div><div class="filters" aria-label="Filter sessions">${[['all','All sessions'],...Object.entries(SKILLS).map(([k,s])=>[k,s.name])].map(([k,n])=>`<button data-filter="${k}" class="${journalFilter===k?'active':''}">${n}</button>`).join('')}</div>${state.draft?'<div class="coach-note"><b>Your unfinished session from the earlier app</b><p class="fine">Your previous answers and notes are preserved below. It has not been counted as a completed session.</p>'+legacyCard({...state.draft,previousDraft:true})+'</div>':''}${sessions.length?sessions.slice().reverse().map((s,i)=>journalCard(s)).join(''):`<div class="panel empty"><div class="empty-symbol">♞</div><h2>${state.sessions.length?'No sessions in this skill yet.':'Your first session starts the story.'}</h2><p>Practice one skill, solve three puzzles, and save your takeaway here.</p><button class="button primary" data-goto="training">Start training</button></div>`}`}
function journalCard(s){if(s.version!==2)return legacyCard(s);let clean=s.results.filter(r=>r.clean).length;return `<details class="panel journal-card"><summary><div><div class="eyebrow">${esc(s.date)} · ${relativeTime(s.seconds)}</div><h3>${SKILLS[s.skill].name} · ${esc(s.lessonTitle)}</h3></div><span class="open-label">View session</span></summary><div class="journal-body"><p class="journal-note"><b>Mistakes I noticed</b>${esc(s.mistakes||'No extra mistakes noted.')}</p><p class="journal-note"><b>My practical tip</b>${esc(s.tip)}</p><div class="instruction">${clean} of ${s.results.length} clean solves · difficulty target ${s.targetStart} to ${s.targetEnd}</div><div class="journal-puzzles">${s.results.map((r,i)=>{let p=puzzleMap.get(r.id);return `<div class="journal-puzzle"><div class="row"><div><b>Puzzle ${i+1} · rated ${p.rating}</b><p class="fine" style="margin:5px 0 0">${r.clean?'Solved first try':r.revealed?'Solution reviewed':'Solved with help'} · ${relativeTime(r.seconds)} · ${r.hints} hints</p></div><button class="button secondary small" data-review="${s.id}:${i}">Review board</button></div>${r.mistakes.length?`<p class="fine" style="margin-top:12px">Moves to learn from: ${r.mistakes.map(m=>esc(m.move)).join(', ')}</p>`:''}</div>`}).join('')}</div></div></details>`}
function legacyBoard(p){let game=new Chess('8/8/8/8/8/8/8/8 w - - 0 1',{skipValidation:true});for(const [sq,c] of Object.entries(p.pos))game.put({type:c.toLowerCase(),color:c===c.toUpperCase()?'w':'b'},sq);return boardHTML(game,{staticBoard:true})}
function legacyCard(s){const l=legacy.find(l=>l.id===s.lesson);if(!l)return '';return `<details class="panel journal-card"><summary><div><div class="eyebrow">${esc(s.date)} · ${s.previousDraft?'unfinished draft':esc(s.minutes)+' minutes'} · previous app</div><h3>${esc(l.skill)} · ${esc(l.title)}</h3></div><span class="open-label">View session</span></summary><div class="journal-body"><p class="journal-note"><b>Mistakes I noticed</b>${esc(s.mistakes||'None noted.')}</p><p class="journal-note"><b>My practical tip</b>${esc(s.tip)}</p><div class="journal-puzzles">${l.p.map((p,i)=>`<div class="journal-puzzle"><b>Puzzle ${i+1}</b>${legacyBoard(p)}<p class="fine">Your move: ${esc(s.answers[i]||'Not recorded')} · ${esc(s.outcomes[i])}</p><div class="instruction"><b>${p.from} to ${p.to}</b><br>${esc(p.text)}</div></div>`).join('')}</div></div></details>`}
function reviewPage(){if(!review)return '<h1>Choose a puzzle from your journal.</h1><button class="button primary" data-goto="journal">Open journal</button>';const original=puzzleMap.get(review.id),p=review.alternative?{...original,moves:[review.alternative]}:original,game=new Chess(p.fen);for(const move of p.moves.slice(0,review.step))game.move(uci(move));let rows=annotations(p),last=rows[review.step-1];return `<div class="intro row"><div><div class="eyebrow">REVIEW · ${SKILLS[p.skill].name.toUpperCase()}</div><h1 style="margin-top:10px">See the whole idea.</h1><p>Puzzle ${p.id} · rated ${p.rating} · Reviewing doesn’t change your difficulty.</p></div><button class="button secondary" data-goto="journal">Back to journal</button></div><div class="training-layout"><div class="board-panel">${boardHTML(game,{black:new Chess(p.fen).turn()==='b',last,staticBoard:true})}<div class="replay-controls"><button class="button secondary" id="review-back" ${review.step===0?'disabled':''}>Previous move</button><button class="button secondary" id="review-next" ${review.step>=p.moves.length?'disabled':''}>Next move</button></div><p class="fine muted section-space">Move ${review.step} of ${p.moves.length}</p></div><div class="panel"><h2>${review.step?esc(last.move):'Start with the position.'}</h2><p>${review.step?esc(last.text):SKILLS[p.skill].tip}</p><div class="solution-line">${solutionHTML(p)}</div><a href="${p.url}" target="_blank" rel="noreferrer" class="fine">Original Lichess puzzle</a></div></div>`}
function progressPage(){const all=state.sessions.filter(s=>s.version===2).flatMap(s=>s.results);return `<div class="intro"><div class="eyebrow">YOUR GAME, OVER TIME</div><h1 style="margin-top:10px">The road to ${fmt(state.profile?.goal||1500)}</h1><p>Record game ratings from the same platform and time control. Puzzle difficulty is tracked separately.</p></div><div class="panel"><div class="row"><h2>${currentRating()==null?'Your first rating starts here.':fmt(currentRating())+' current game rating'}</h2><span class="badge">Goal ${fmt(state.profile?.goal||1500)}</span></div>${chart()}</div><form class="panel section-space" id="rating-form"><h2>Record a rating update</h2><div class="form-grid"><label class="form-field">Date<input name="date" type="date" value="${localDate()}" max="${localDate()}" required></label><label class="form-field">Game rating<input name="value" type="number" min="100" max="3500" step="1" placeholder="For example, 975" required></label><label class="form-field full">Platform / time control<input name="source" value="${esc(state.profile?.platform||'')}" placeholder="For example, Lichess rapid" required></label></div><button class="button primary section-space">Save rating update</button></form><div class="panel section-space"><h2>Rating history</h2>${state.ratings.length?`<table class="table"><thead><tr><th>Date</th><th>Platform / time control</th><th>Rating</th></tr></thead><tbody>${state.ratings.slice().reverse().map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.source)}</td><td>${fmt(r.value)}</td></tr>`).join('')}</tbody></table>`:'<p class="fine">No updates recorded yet. You can train without a game rating.</p>'}</div>${state.coach?`<div class="section-space"><h2>Your training difficulty</h2><p class="fine">Targets adapt independently for each skill. These are not game-rating estimates.</p><div class="skill-cards">${Object.entries(SKILLS).map(([k,s])=>`<div class="skill-card"><b>${s.name}</b><div class="metric-number" style="font-size:27px">${fmt(skillCoach(k).target)}</div><small>${skillCoach(k).total} attempted · ${skillCoach(k).solved} clean solves</small></div>`).join('')}</div></div>`:''}`}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='chess-daily-'+localDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported. Keep it somewhere safe.')}
async function importData(event){try{const file=event.target.files[0];if(!file)return;if(file.size>10_000_000)throw Error();const raw=JSON.parse(await file.text());if(!validBackup(raw,new Set(bank.map(p=>p.id))))throw Error();if(raw.active?.puzzle&&raw.active.puzzle.cursor>puzzleMap.get(raw.active.puzzle.id).moves.length)throw Error();if(!confirm('Replace this browser’s records with the backup? Export your current records first if you want to keep them.'))return;state=normalize(raw);paused=true;save();go('dashboard');toast('Your backup has been restored.')}catch{toast('That backup could not be opened. Choose a Chess, daily JSON export.')}finally{event.target.value=''}}
function bind(){ $$('[data-goto]').forEach(b=>b.onclick=()=>go(b.dataset.goto));$$('[data-task]').forEach(c=>c.onchange=()=>{state.checks[weekKey()]||={};state.checks[weekKey()][c.dataset.task]=c.checked;save();render()});$$('[data-skill]').forEach(b=>b.onclick=()=>{selectedSkill=b.dataset.skill;render()});if($('#begin-session'))$('#begin-session').onclick=beginSession;
if($('#profile-form')){const form=$('#profile-form');$$('input[name="known"]').forEach(r=>r.onchange=()=>{const known=form.elements.known.value==='yes';$('#current-rating').disabled=!known;$('#current-rating').required=known;});form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),rating=f.get('known')==='yes'?Number(f.get('current')):null,goal=Number(f.get('goal'));if(rating!=null&&(rating<100||rating>3500)||goal<100||goal>3500)return;let first=!state.profile,old=state.profile,previousRating=currentRating();state.profile={currentRating:rating,goal,platform:String(f.get('platform')||''),startRating:old?.startRating??rating};if(rating!=null&&rating!==previousRating)state.ratings.push({date:localDate(),value:rating,source:state.profile.platform||'Starting rating'});if(first||f.get('recalibrate'))state.coach=newCoach(rating);save();go('dashboard');toast(first?'Your training plan is ready.':'Training plan saved.')}}
$$('[data-square]').forEach(b=>b.onclick=()=>trySquare(b.dataset.square));if($('#flip-board'))$('#flip-board').onclick=()=>{flipped=!flipped;render()};if($('#pause'))$('#pause').onclick=()=>{flushTime();paused=!paused;lastTick=Date.now();render()};if($('#resume-board'))$('#resume-board').onclick=()=>{paused=false;lastTick=Date.now();render()};if($('#hint'))$('#hint').onclick=()=>{flushTime();const a=state.active.puzzle;a.hints=Math.min(2,a.hints+1);selectedSquare=null;save();render()};if($('#reveal'))$('#reveal').onclick=()=>{flushTime();finishPuzzle(true)};if($('#next-puzzle'))$('#next-puzzle').onclick=()=>{flushTime();const d=state.active;if(d.results.length>=3)d.stage='notes';else newPuzzle();save();render();window.scrollTo({top:0,behavior:'instant'})};if($('#replay-back'))$('#replay-back').onclick=()=>{const p=puzzleMap.get(state.active.puzzle.id);replayStep=Math.max(0,(replayStep??p.moves.length)-1);render()};if($('#replay-next'))$('#replay-next').onclick=()=>{const p=puzzleMap.get(state.active.puzzle.id);replayStep=Math.min(p.moves.length,(replayStep??p.moves.length)+1);render()};$$('[data-note]').forEach(i=>i.oninput=()=>{state.active[i.dataset.note]=i.value;save()});if($('#save-session'))$('#save-session').onsubmit=e=>{e.preventDefault();saveSession()};$$('[data-filter]').forEach(b=>b.onclick=()=>{journalFilter=b.dataset.filter;render()});$$('[data-review]').forEach(b=>b.onclick=()=>{let [id,index]=b.dataset.review.split(':'),s=state.sessions.find(s=>String(s.id)===id);review={id:s.results[Number(index)].id,alternative:s.results[Number(index)].alternative,step:0};go('review')});if($('#review-back'))$('#review-back').onclick=()=>{review.step--;render()};if($('#review-next'))$('#review-next').onclick=()=>{review.step++;render()};if($('#rating-form'))$('#rating-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),r={date:f.get('date'),value:Number(f.get('value')),source:String(f.get('source')).trim()};if(!r.source||r.value<100||r.value>3500)return;state.ratings.push(r);state.ratings.sort((a,b)=>a.date.localeCompare(b.date));if(state.profile&&state.profile.startRating==null)state.profile.startRating=r.value;save();render();toast('Game rating saved. Puzzle difficulty still follows your solves.')};$$('[data-export]').forEach(b=>b.onclick=exportData);$$('.restore-file').forEach(f=>f.onchange=importData);}
$$('nav button').forEach(b=>b.onclick=()=>go(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();go('dashboard')};$('#export').onclick=exportData;$('#import').onchange=importData;$('#cancel-promotion').onclick=()=>{pendingPromotion=null;$('#promotion').close()};document.addEventListener('visibilitychange',()=>{flushTime();lastTick=Date.now()});window.addEventListener('beforeunload',()=>{flushTime();save()});setInterval(()=>{flushTime();if($('#session-time')&&state.active)$('#session-time').textContent=duration(state.active.seconds);if($('#puzzle-time')&&state.active?.puzzle)$('#puzzle-time').textContent=relativeTime(state.active.puzzle.seconds)},1000);
try{const [p,l]=await Promise.all([fetch('puzzles.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('legacy-lessons.json').then(r=>r.json())]);bank=p;legacy=l;puzzleMap=new Map(bank.map(p=>[p.id,p]));if(state.profile&&!state.coach)state.coach=newCoach(currentRating());if(state.active&&!puzzleMap.has(state.active.puzzle?.id))state.active=null;render()}catch{$('#content').innerHTML='<div class="panel empty"><h1>Your training room couldn’t load.</h1><p>Check your connection and reload. Your saved records are still in this browser.</p><button class="button primary" id="reload-app">Reload training room</button></div>';$('#reload-app').onclick=()=>location.reload();}
